echo "=== Listar todos los Cloud NAT routers + sus IPs externas (todos los proyectos/regiones) ==="
for proj in prod-apps-454414 stg-apps-454414 qa-apps-454414 shared-016 liftit-bi security-454414 liftit-production; do
  echo "--- $proj ---"
  for region in us-east1 us-central1 us-east4 us-west1; do
    gcloud compute routers list --project=$proj --filter="region:$region" --format='value(name)' 2>/dev/null | while read r; do
      [ -z "$r" ] && continue
      ips=$(gcloud compute routers get-nat-ip-info $r --region=$region --project=$proj --format=json 2>/dev/null)
      if [ -n "$ips" ] && [ "$ips" != "[]" ]; then
        echo "  router=$r region=$region"
        echo "$ips" | python3 -c "import json,sys
d=json.load(sys.stdin)
for r in d.get('result',{}).get('natIpInfoMapping',[]) if isinstance(d,dict) else []:
    for ip in r.get('natIpInfo',[]):
        print('    NAT IP:',ip.get('natIp'))" 2>/dev/null || echo "$ips" | python3 -c "import json,sys
d=json.load(sys.stdin)
def walk(o):
    if isinstance(o,dict):
        if 'natIp' in o: print('    NAT IP:',o['natIp'])
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(d)" 2>/dev/null
      fi
    done
  done
done

